add_md("""---
## Section 3: Dataset Ingestion, Nearest Resizing & Memory-Safe uint8 Quantization

To prevent the fatal **2 GB TensorFlow GraphDef protobuf serialization crash**, we:
1. Store sprites as a **`uint8` index matrix** of shape `(N, 64, 64)` (~172 MB in RAM).
2. Construct a compact Look-Up Table (LUT) of shape `(33, 4)` for discrete RGBA in $[-1, 1]$.
3. Expand indices on the fly during training via `tf.gather(lut_tf, idx)`.""")

add_code("""from datasets import load_dataset

print(f"Loading '{HF_DATASET_NAME}' from HuggingFace Hub...")
raw_ds = load_dataset(HF_DATASET_NAME, split="train")
print(f"Raw dataset loaded: {len(raw_ds):,} total entries")

# Locate front-facing indices
INDICES_CANDIDATES = [
    f"{CONFIG_DIR}/{INDICES_FILE_NAME}",
    f"Notebook/training/{INDICES_FILE_NAME}",
    f"/kaggle/input/alucard-frontfacing/{INDICES_FILE_NAME}",
    f"/kaggle/input/alucard-frontfacing-dataset/{INDICES_FILE_NAME}",
    f"phase_dcgan_improvement/dataset_research/final_alucard_frontfacing_manifest.csv",
    f"/kaggle/input/alucard-frontfacing/final_alucard_frontfacing_manifest.csv",
    f"models/dcgan_frontfacing_clean_50ep_results/config/strictly_front_facing_indices.json"
]

curated_indices = None
for path_cand in INDICES_CANDIDATES:
    if os.path.exists(path_cand):
        print(f"Found front-facing dataset file: {path_cand}")
        if path_cand.endswith(".csv"):
            import pandas as pd
            df_m = pd.read_csv(path_cand)
            df_train = df_m[df_m["grouped_split"] == "train"] if "grouped_split" in df_m.columns else df_m
            curated_indices = [int(x) for x in df_train["archive_index"].tolist()]
        else:
            with open(path_cand, "r") as f:
                curated_indices = json.load(f)
        print(f"Loaded {len(curated_indices):,} indices from {path_cand}.")
        break

# Self-contained fallback: Unpack pre-embedded 42,212 front-facing indices if not found on disk
if not curated_indices:
    import zlib, base64
    print("Candidate files not found on disk. Unpacking pre-embedded 42,212 front-facing indices...")
    EMBEDDED_B64 = ""
    curated_indices = json.loads(zlib.decompress(base64.b64decode(EMBEDDED_B64.encode('ascii'))).decode('utf-8'))
    print(f"Successfully unpacked {len(curated_indices):,} embedded front-facing indices!")

# Save indices in config dir for reproducibility
with open(f"{CONFIG_DIR}/{INDICES_FILE_NAME}", "w") as f:
    json.dump(curated_indices, f)

# Select dataset items
selected_ds = raw_ds.select(curated_indices)
N_SPRITES = len(selected_ds)
print(f"Total curated front-facing sprites: {N_SPRITES:,}")

# ── Step 1: Preload Sprites with Nearest Resizing & Binary Alpha ──────────────
print("Preloading sprites with Nearest-Neighbor resize & binary alpha into RAM...")
t0 = time.time()
raw_images = np.zeros((N_SPRITES, IMG_HEIGHT, IMG_WIDTH, CHANNELS), dtype=np.uint8)

for i, sample in enumerate(selected_ds):
    img = sample["image"].convert("RGBA")
    if img.size != (IMG_WIDTH, IMG_HEIGHT):
        img = img.resize((IMG_WIDTH, IMG_HEIGHT), PILImage.NEAREST)
    arr = np.asarray(img, dtype=np.uint8)
    
    # Binary alpha threshold
    fg = arr[..., 3] > 127
    arr_clean = np.zeros_like(arr)
    arr_clean[fg, :3] = arr[fg, :3]
    arr_clean[fg, 3] = 255
    raw_images[i] = arr_clean
    
    if (i + 1) % 10000 == 0 or i == N_SPRITES - 1:
        print(f"  Loaded {i+1:,}/{N_SPRITES:,} sprites ({time.time() - t0:.1f}s)")

# ── Step 2: Build Empirical 32-Color Global Palette ───────────────────────────
print("\\nFitting 32-color Global Palette on foreground pixels from 3,000 reference sprites...")
sample_indices = np.random.RandomState(SEED).choice(N_SPRITES, size=min(3000, N_SPRITES), replace=False)
fg_pixels = []
for idx in sample_indices:
    spr = raw_images[idx]
    fg_mask = spr[..., 3] == 255
    if np.any(fg_mask):
        fg_pixels.append(spr[fg_mask, :3])

fg_pixels = np.concatenate(fg_pixels, axis=0)
print(f"Collected {len(fg_pixels):,} foreground pixels. Running MiniBatchKMeans (K={PALETTE_SIZE})...")

kmeans = MiniBatchKMeans(n_clusters=PALETTE_SIZE, batch_size=4096, random_state=SEED, n_init=3)
kmeans.fit(fg_pixels)
global_palette_u8 = np.clip(kmeans.cluster_centers_, 0, 255).astype(np.uint8)
np.save(f"{CONFIG_DIR}/global_palette_32.npy", global_palette_u8)
print("Global 32-color palette constructed and saved.")

# ── Step 3: Quantize Sprites to uint8 Index Array (Memory Safe: ~172 MB) ──────
print("\\nQuantizing all 42K training sprites to uint8 palette indices...")
idx_dataset = np.full((N_SPRITES, IMG_HEIGHT, IMG_WIDTH), BG_INDEX, dtype=np.uint8)
palette_float = global_palette_u8.astype(np.float32)

for i in range(N_SPRITES):
    spr = raw_images[i]
    fg = spr[..., 3] == 255
    if not np.any(fg):
        continue
    
    rgb = spr[..., :3].astype(np.float32)
    dists = np.sum((rgb[fg][:, None, :] - palette_float[None, :, :]) ** 2, axis=-1)
    nearest_idx = np.argmin(dists, axis=-1)
    idx_dataset[i][fg] = nearest_idx

del raw_images
gc.collect()

# ── Step 4: Construct Compact Look-Up Table (LUT) ─────────────────────────────
# lut: shape (33, 4) in [-1, 1]. Indices 0..31 are palette colors with Alpha=1.0. Index 32 is RGBA=(-1,-1,-1,-1).
lut = np.concatenate([
    np.concatenate([global_palette_u8 / 127.5 - 1.0, np.ones((PALETTE_SIZE, 1))], axis=1),
    -np.ones((1, 4))
], axis=0).astype(np.float32)

lut_tf = tf.constant(lut, dtype=tf.float32)
global_palette_tf = tf.constant(global_palette_u8 / 255.0, dtype=tf.float32)

print(f"Quantization complete! uint8 Index Matrix: {idx_dataset.nbytes / (1024**2):.1f} MB (No 2GB protobuf limit risk).")""")

