## Section 4: Real Dataset Verification Grid & Baseline Coherence Metrics""")

add_code("""def compute_sprite_stats(imgs_neg1_to_1):
    \"\"\"Computes comprehensive sprite metrics: unique colors, spatial coherence, foreground fraction, and diversity.\"\"\"
    imgs01 = (imgs_neg1_to_1 + 1.0) * 0.5
    u8 = np.round(imgs01 * 255.0).astype(np.uint8)
    uniq_list, adj_list, fg_area_list = [], [], []
    
    for im in u8:
        fg = im[..., 3] > 127
        fg_area_list.append(np.mean(fg))
        if not np.any(fg):
            uniq_list.append(0)
            adj_list.append(0.0)
            continue
        uniq_list.append(len(np.unique(im[fg][:, :3], axis=0)))
        same_h = (im[:, 1:, :3] == im[:, :-1, :3]).all(-1)
        valid_adj = fg[:, 1:] & fg[:, :-1]
        if np.any(valid_adj):
            adj_list.append(same_h[valid_adj].mean())
        else:
            adj_list.append(0.0)
            
    # Pairwise L1 diversity
    flat = imgs01.reshape(len(imgs01), -1)
    if len(flat) > 1:
        diffs = np.abs(flat[:, None, :] - flat[None, :, :]).mean(axis=-1)
        np.fill_diagonal(diffs, np.nan)
        diversity = float(np.nanmean(diffs))
    else:
        diversity = 0.0
        
    return float(np.mean(uniq_list)), float(np.mean(adj_list)), float(np.mean(fg_area_list)), diversity

real_sample_indices = np.random.RandomState(SEED).choice(N_SPRITES, size=36, replace=False)
real_sample_batch = lut[idx_dataset[real_sample_indices]]
real_unique_colors, real_spatial_coherence, real_fg_area, real_diversity = compute_sprite_stats(real_sample_batch)

print("=" * 75)
print("REAL DATASET GROUND TRUTH BENCHMARKS (AUDITED BASELINE):")
print(f"  Average Unique Colors per Sprite : {real_unique_colors:.1f} (Discrete Target: 10-32)")
print(f"  Spatial Color Coherence Ratio    : {real_spatial_coherence * 100:.2f}% (Planar Target: > 35%)")
print(f"  Foreground Area Fraction         : {real_fg_area * 100:.2f}% (Target: ~20-35%)")
print(f"  Pairwise L1 Diversity Score      : {real_diversity:.4f} (Mode Collapse Prevention)")
print("=" * 75)

# Plot 6x6 Verification Grid
fig, axes = plt.subplots(6, 6, figsize=(10, 10))
for idx, ax in enumerate(axes.flat):
    img_data = (real_sample_batch[idx] + 1.0) * 0.5
    img_rgba = np.clip(img_data * 255.0, 0, 255).astype(np.uint8)
    ax.imshow(img_rgba)
    ax.axis('off')
plt.suptitle(f"Real Quantized Front-Facing Sprites (32-Color Discrete Ground Truth)", fontsize=13)
plt.tight_layout()
plt.savefig(f"{CONFIG_DIR}/real_characters_inspection.png", dpi=150)
plt.close()
print(f"Saved real inspection grid to {CONFIG_DIR}/real_characters_inspection.png")""")

# ==============================================================================
# CELL 5: GENERATOR & DISCRIMINATOR ARCHITECTURES
# ==============================================================================
add_md("""---
## Section 5: Model Architectures

1. **Generator:**
   - 4-stage nearest upsampling backbone ($4 \\times 4 \\to 64 \\times 64$).
   - Full-resolution $64 \\times 64$ refinement convolution.
   - Outputs $K+1$ logits ($K=32$ colors + 1 alpha logit).
   - `logits_to_image()` straight-through Gumbel-Softmax maps logits to hard discrete palette colors while streaming continuous gradients backward.
2. **Discriminator:**
   - 4 strided convolutions wrapped in `SpectralNormalization`.
   - **NO BatchNorm & NO Dropout** (eliminates batch-stat shortcuts and gradient noise).
   - Dense(1) linear scalar output for geometric Hinge Loss.""")

add_code("""# Straight-Through Gumbel-Softmax Image Synthesizer
def logits_to_image(logits, palette_tf, tau=1.0, hard=True, noise=True):
    \"\"\"
    Converts (B, 64, 64, K+1) logits into discrete RGBA images in [-1, 1].
    palette_tf: (K, 3) float32 tensor in [0, 1].
    Uses Straight-Through Gumbel-Softmax for hard forward pass and smooth gradient flow.
    \"\"\"
    pl = logits[..., :PALETTE_SIZE]
    al = logits[..., PALETTE_SIZE:]
    
    if noise:
        u = tf.random.uniform(tf.shape(pl), minval=1e-6, maxval=1.0)
        gumbel_noise = -tf.math.log(-tf.math.log(u))
        pl = pl + gumbel_noise
        
    ys = tf.nn.softmax(pl / tau, axis=-1)
    if hard:
        y_hard = tf.one_hot(tf.argmax(ys, axis=-1), depth=PALETTE_SIZE, dtype=tf.float32)
        y = tf.stop_gradient(y_hard - ys) + ys
    else:
        y = ys
        
    # Discrete RGB reconstruction in [0, 1]
    rgb = tf.tensordot(y, palette_tf, axes=[[-1], [0]])
    
    # Binary Alpha Masking in [0, 1]
    a_s = tf.sigmoid(al)
    if hard:
        a_hard = tf.cast(a_s > 0.5, dtype=tf.float32)
        a = tf.stop_gradient(a_hard - a_s) + a_s
    else:
        a = a_s
        
    # Map to [-1, 1] where transparent background = -1.0
    img_01 = tf.concat([rgb * a, a], axis=-1)
    return img_01 * 2.0 - 1.0

def build_generator(latent_dim=LATENT_DIM):
    z_in = layers.Input(shape=(latent_dim,), name="latent_vector")
    x = layers.Dense(G_INIT_SPATIAL * G_INIT_SPATIAL * G_CHANNELS[0], use_bias=False)(z_in)
    x = layers.BatchNormalization()(x)
    x = layers.LeakyReLU(0.2)(x)
    x = layers.Reshape((G_INIT_SPATIAL, G_INIT_SPATIAL, G_CHANNELS[0]))(x)
    
    # 4x4 -> 8x8
    x = layers.UpSampling2D(size=(2, 2), interpolation="nearest")(x)
    x = layers.Conv2D(G_CHANNELS[1], (3, 3), padding="same", use_bias=False)(x)
    x = layers.BatchNormalization()(x)
    x = layers.LeakyReLU(0.2)(x)
    
    # 8x8 -> 16x16
    x = layers.UpSampling2D(size=(2, 2), interpolation="nearest")(x)
    x = layers.Conv2D(G_CHANNELS[2], (3, 3), padding="same", use_bias=False)(x)
    x = layers.BatchNormalization()(x)
    x = layers.LeakyReLU(0.2)(x)
    
    # 16x16 -> 32x32
    x = layers.UpSampling2D(size=(2, 2), interpolation="nearest")(x)
    x = layers.Conv2D(G_CHANNELS[3], (3, 3), padding="same", use_bias=False)(x)
    x = layers.BatchNormalization()(x)
    x = layers.LeakyReLU(0.2)(x)
    
    # 32x32 -> 64x64
    x = layers.UpSampling2D(size=(2, 2), interpolation="nearest")(x)
    x = layers.Conv2D(64, (3, 3), padding="same", use_bias=False)(x)
    x = layers.BatchNormalization()(x)
    x = layers.LeakyReLU(0.2)(x)
    
    # Full-Resolution 64x64 Refinement Layer
    x = layers.Conv2D(64, (3, 3), padding="same")(x)
    x = layers.LeakyReLU(0.2)(x)
    
    # Discrete K+1 Logits Head (32 color logits + 1 alpha logit)
    logits = layers.Conv2D(PALETTE_SIZE + 1, (3, 3), padding="same", name="palette_logits")(x)
    return keras.Model(z_in, logits, name="Discrete_DCGAN_Generator")

def build_discriminator():
    img_in = layers.Input(shape=(IMG_HEIGHT, IMG_WIDTH, CHANNELS), name="sprite_input")
    
    def sn_conv(filters, strides=2):
        conv = layers.Conv2D(filters, (4, 4), strides=strides, padding="same")
        return layers.SpectralNormalization(conv)
    
    x = sn_conv(D_CHANNELS[0])(img_in)
    x = layers.LeakyReLU(0.2)(x)
    
    x = sn_conv(D_CHANNELS[1])(x)
    x = layers.LeakyReLU(0.2)(x)
    
    x = sn_conv(D_CHANNELS[2])(x)
    x = layers.LeakyReLU(0.2)(x)
    
    x = sn_conv(D_CHANNELS[3])(x)
    x = layers.LeakyReLU(0.2)(x)
    
    x = layers.Flatten()(x)
    out = layers.Dense(1, name="scalar_score")(x)
    return keras.Model(img_in, out, name="Spectral_Discriminator")

with strategy.scope():
    generator = build_generator()
    discriminator = build_discriminator()

print("Model Architectures Initialized under Strategy:")
print(f"  Generator Parameters     : {generator.count_params():,}")
print(f"  Discriminator Parameters : {discriminator.count_params():,}")""")

# ==============================================================================
# CELL 6: DIFFAUGMENT, HINGE LOSS & DISTRIBUTED TRAINING STEP
# ==============================================================================
add_md("""---
## Section 6: Translation DiffAugment, Hinge Loss & Training Step""")

add_code("""# Fully Vectorized Translation DiffAugment (Zero tf.map_fn, 100% MirroredStrategy Compatible)
with strategy.scope():
    aug_layer = layers.RandomTranslation(
        height_factor=(-DIFFAUG_PAD / float(IMG_HEIGHT), DIFFAUG_PAD / float(IMG_HEIGHT)),
        width_factor=(-DIFFAUG_PAD / float(IMG_WIDTH), DIFFAUG_PAD / float(IMG_WIDTH)),
        fill_mode="constant",
        fill_value=-1.0,
        interpolation="nearest"
    )

def diff_aug_translation(x):
    return aug_layer(x, training=True)

with strategy.scope():
    g_optimizer = keras.optimizers.Adam(learning_rate=G_LR, beta_1=ADAM_BETA1, beta_2=ADAM_BETA2)
    d_optimizer = keras.optimizers.Adam(learning_rate=D_LR, beta_1=ADAM_BETA1, beta_2=ADAM_BETA2)
    
    # Pre-build optimizer slot variables under strategy scope to prevent placeholder uninitialized graph crash
    g_optimizer.build(generator.trainable_variables)
    d_optimizer.build(discriminator.trainable_variables)

# ── Unified Replica Step (MirroredStrategy Compatible) ─────────────────────
def train_step_per_replica(real_imgs):
    local_batch = tf.shape(real_imgs)[0]
    z = tf.random.normal((local_batch, LATENT_DIM))
    
    # 1. Update Discriminator
    with tf.GradientTape() as d_tape:
        fake_logits_d = generator(z, training=True)
        fake_imgs_d = logits_to_image(fake_logits_d, global_palette_tf, tau=1.0, hard=True, noise=True)
        
        real_aug = diff_aug_translation(real_imgs)
        fake_aug_d = diff_aug_translation(fake_imgs_d)
        
        d_real = discriminator(real_aug, training=True)
        d_fake = discriminator(fake_aug_d, training=True)
        
        d_loss = tf.reduce_mean(tf.nn.relu(1.0 - d_real)) + tf.reduce_mean(tf.nn.relu(1.0 + d_fake))
        
    d_grads = d_tape.gradient(d_loss, discriminator.trainable_variables)
    d_optimizer.apply_gradients(zip(d_grads, discriminator.trainable_variables))
    
    # 2. Update Generator
    with tf.GradientTape() as g_tape:
        fake_logits_g = generator(z, training=True)
        fake_imgs_g = logits_to_image(fake_logits_g, global_palette_tf, tau=1.0, hard=True, noise=True)
        fake_aug_g = diff_aug_translation(fake_imgs_g)
        
        d_fake_g = discriminator(fake_aug_g, training=True)
        g_loss = -tf.reduce_mean(d_fake_g)
        
    g_grads = g_tape.gradient(g_loss, generator.trainable_variables)
    g_optimizer.apply_gradients(zip(g_grads, generator.trainable_variables))
    
    return d_loss, g_loss

@tf.function
def distributed_train_step(dist_real_images):
    per_d, per_g = strategy.run(train_step_per_replica, args=(dist_real_images,))
    d_loss = strategy.reduce(tf.distribute.ReduceOp.MEAN, per_d, axis=None)
    g_loss = strategy.reduce(tf.distribute.ReduceOp.MEAN, per_g, axis=None)
    return d_loss, g_loss

print("Distributed Hinge Training Step compiled.")
print("Executing 1-step warmup across GPU replicas to initialize all optimizer states...")
dummy_ds = tf.data.Dataset.from_tensors(
    tf.zeros((GLOBAL_BATCH_SIZE, IMG_HEIGHT, IMG_WIDTH, CHANNELS), dtype=tf.float32)
)
dist_dummy = strategy.experimental_distribute_dataset(dummy_ds)
distributed_train_step(next(iter(dist_dummy)))
print("Warmup: SUCCESS! All replica optimizer states initialized cleanly.")""")

# ==============================================================================
