    synth_imgs = logits_to_image(raw_logits, global_palette_tf, tau=0.8, hard=True, noise=False).numpy()
    
    # Compute gate metrics
    gen_uniq, gen_coh, gen_fg, gen_div = compute_sprite_stats(synth_imgs)
    
    fig, axes = plt.subplots(6, 6, figsize=(10, 10))
    for idx, ax in enumerate(axes.flat):
        img_data = (synth_imgs[idx] + 1.0) * 0.5
