# Checkpoint Manager
ckpt = tf.train.Checkpoint(generator=generator, discriminator=discriminator, g_optimizer=g_optimizer, d_optimizer=d_optimizer)
ckpt_manager = tf.train.CheckpointManager(ckpt, CKPT_DIR, max_to_keep=3)

print("Starting Discrete DCGAN Training Loop...")
print(f"Total Epochs: {TARGET_EPOCHS} | Steps per Epoch: {STEPS_PER_EPOCH:,}")

history_csv_path = f"{LOG_DIR}/training_history.csv"
with open(history_csv_path, "w") as f:
    f.write("epoch,d_loss,g_loss,gen_colors,gen_coherence,gen_fg_area,gen_diversity,epoch_time\\n")

for epoch in range(1, TARGET_EPOCHS + 1):
    t_start = time.time()
    
    # On-device tensor accumulation to eliminate per-step GPU sync
    d_loss_accum = tf.constant(0.0)
    g_loss_accum = tf.constant(0.0)
    
    for step, real_batch in enumerate(dist_dataset):
        d_l, g_l = distributed_train_step(real_batch)
        d_loss_accum += d_l
        g_loss_accum += g_l
        
    avg_d = float(d_loss_accum.numpy()) / STEPS_PER_EPOCH
    avg_g = float(g_loss_accum.numpy()) / STEPS_PER_EPOCH
    elapsed = time.time() - t_start
    
    gen_c, gen_coh, gen_fg, gen_div = 0.0, 0.0, 0.0, 0.0
    if epoch % SAMPLE_EVERY == 0 or epoch == 1:
        gen_c, gen_coh, gen_fg, gen_div = generate_and_save_samples(epoch)
        status_tag = "PASS" if gen_coh >= 0.25 else "WARN: LOW COHERENCE"
        print(f"Epoch {epoch:02d}/{TARGET_EPOCHS} | D_Loss: {avg_d:.4f} | G_Loss: {avg_g:.4f} | "
              f"Colors: {gen_c:.1f} | Coherence: {gen_coh*100:.1f}% | Div: {gen_div:.3f} [{status_tag}] | Time: {elapsed:.1f}s")
        
        if epoch >= 6 and gen_coh < 0.20:
            print(f"  [GATE ADVISORY]: Coherence is {gen_coh*100:.1f}%. Optimization progressing...")
    else:
        print(f"Epoch {epoch:02d}/{TARGET_EPOCHS} | D_Loss: {avg_d:.4f} | G_Loss: {avg_g:.4f} | Time: {elapsed:.1f}s")
        
    with open(history_csv_path, "a") as f:
        f.write(f"{epoch},{avg_d:.4f},{avg_g:.4f},{gen_c:.2f},{gen_coh:.4f},{gen_fg:.4f},{gen_div:.4f},{elapsed:.1f}\\n")
        
    if epoch % CHECKPOINT_EVERY == 0:
        save_path = ckpt_manager.save()
        print(f"  Checkpoint saved: {save_path}")

